// Each linked material stays far below 16 samplers; circuits use uniform vectors.
export function createL0Materials(T,renderer){
 const pending=[],loader=new T.TextureLoader(),cache=new Map();
 const uniforms={time:{value:0},brightness:{value:1},cutCount:{value:0},cuts:{value:Array.from({length:12},()=>new T.Vector4(0,0,0,0))}};
 const tex=(file,color=false,old=false)=>{const url='./assets/'+(old?'level0/':'level0-v2/')+file;if(cache.has(url))return cache.get(url);let resolve,reject;pending.push(new Promise((a,b)=>{resolve=a;reject=b;}));const t=loader.load(url,resolve,undefined,reject);t.wrapS=t.wrapT=T.RepeatWrapping;t.colorSpace=color?T.SRGBColorSpace:T.NoColorSpace;t.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());cache.set(url,t);return t;};
 const plain=(color,roughness=.9)=>new T.MeshStandardMaterial({color,roughness});
 const standard=(name,color=0xffffff,scale=null,roughness=.94)=>{const m=new T.MeshStandardMaterial({map:tex(name+'.webp',true),normalMap:tex(name+'-normal.webp'),normalScale:new T.Vector2(.25,.25),color,roughness});m.userData.worldScale=scale;return m;};
 const wall=[standard('wallpaper-chevron',0xf8f6e9,1.02),standard('wallpaper-dots',0xf7f4e6,1.12),plain(0xd3cfb8)];wall[0].userData.albedoRemap='wall';wall[1].userData.albedoRemap='wall';
 const carpet=standard('carpet-reference',0xffffff,2.0,.98);carpet.normalScale.set(.09,.09);carpet.userData.albedoRemap='carpet';
 const ceiling=new T.MeshStandardMaterial({map:tex('ceiling-acoustic-albedo.jpg',true,true),normalMap:tex('ceiling-acoustic-albedo-normal.png',false,true),normalScale:new T.Vector2(.13,.13),color:0xd1cebb,roughness:.97,emissive:0xc6c3a8,emissiveIntensity:.16});ceiling.userData.worldScale=1.2;ceiling.userData.albedoRemap='ceiling';
 const insulation=new T.MeshStandardMaterial({map:tex('insulation-fiberglass-albedo.jpg',true,true),normalMap:tex('insulation-fiberglass-albedo-normal.png',false,true),normalScale:new T.Vector2(.6,.6),color:0xe3dabe,roughness:1,side:T.DoubleSide});insulation.userData.worldScale=.45;insulation.userData.albedoRemap='insulation';
 const mats={wall,carpet,ceiling,insulation,pink:insulation.clone(),wood:standard('furniture-oak',0xbdbbad,null),walnut:standard('furniture-walnut',0xffffff,null),metal:standard('duct-galvanized',0xd3d2c9,null,.78),grid:plain(0xc5c3b6),dark:plain(0x1c1c19),copper:plain(0x965830,.6),orange:plain(0xb96727,.7),pale:plain(0xc9c7b2),trim:plain(0xb8af88),red:standard('wallpaper-chevron',0x813f35,1.02),redFloor:standard('carpet-reference',0x9a6558,2,.98),lamp:new T.MeshBasicMaterial({color:0xfffef2,toneMapped:false}),lampOff:plain(0x676658),void:new T.MeshBasicMaterial({color:0x090908}),fabric:plain(0xbfbba3),socketIvory:plain(0xc3b996,.74),socketBrown:plain(0x4d3323,.63),socketWhite:plain(0xd7d8cf,.68),steel:plain(0x828984,.68),blackPlastic:plain(0x292e2a,.76),screen:new T.MeshStandardMaterial({color:0x18272b,roughness:.30,metalness:.25}),bin:standard('bucket-burgundy',0xffffff,null,.82),pail:standard('bucket-pail',0xffffff,null,.68)};
 mats.pink.color.set(0xffffff);mats.pink.userData.albedoRemap="pink";mats.pale.normalMap=wall[0].normalMap;mats.pale.normalScale=new T.Vector2(.05,.05);mats.metal.metalness=.20;
 mats.panels=Array.from({length:10},(_,i)=>{const m=standard('panel-'+String(i+1).padStart(2,'0'));m.normalScale.set(.36,.36);return m;});
 mats.outlets=Array.from({length:5},(_,i)=>new T.MeshStandardMaterial({map:tex('outlet-'+String(i+1).padStart(2,'0')+'.webp',true),roughness:.83}));
 mats.breaker=new T.MeshStandardMaterial({map:tex('breaker-panel.webp',true),roughness:.78});
 mats.mold=new T.MeshStandardMaterial({map:tex('mold-patch.webp',true),transparent:true,alphaTest:.025,depthWrite:false,roughness:1,polygonOffset:true,polygonOffsetFactor:-2});
 for(const [key,file] of [['floral','sofa-floral'],['teal','sofa-teal'],['velour','sofa-velour']])mats[key]=new T.MeshPhysicalMaterial({map:tex(file+'.webp',true),displacementMap:tex(file+'-height.webp'),displacementScale:.006,displacementBias:-.003,roughness:.97,sheen:.48,sheenColor:new T.Color(0xd9ceb6),sheenRoughness:.88});
 const cutGLSL='uniform int cutCount;uniform vec4 cuts[12];float circuitAt(vec3 p){float a=1.;for(int i=0;i<12;i++){if(i>=cutCount)break;float d=distance(p.xz,cuts[i].xy);a*=mix(1.,.038,(1.-smoothstep(cuts[i].z*.82,cuts[i].z,d))*cuts[i].w);}return a;}';
 function decorate(m){const scale=m.userData.worldScale,remap=m.userData.albedoRemap;const grade=remap==='carpet'?'sampledDiffuseColor.rgb=mix(sampledDiffuseColor.rgb,vec3(.47,.43,.34),.68);':remap==='insulation'?'sampledDiffuseColor.rgb=mix(sampledDiffuseColor.rgb,vec3(.66,.47,.18),.62);':remap==='pink'?'sampledDiffuseColor.rgb=mix(sampledDiffuseColor.rgb,vec3(.63,.40,.39),.65);':remap==='ceiling'?'sampledDiffuseColor.rgb=mix(sampledDiffuseColor.rgb,vec3(.53,.52,.46),.55);':remap==='wall'?'sampledDiffuseColor.rgb=mix(sampledDiffuseColor.rgb,vec3(.64,.60,.42),.38);':'';m.onBeforeCompile=s=>{s.uniforms.cutCount=uniforms.cutCount;s.uniforms.cuts=uniforms.cuts;s.vertexShader=s.vertexShader.replace('#include <common>','#include <common>\nvarying vec3 l0World;varying vec3 l0Normal;');s.vertexShader=s.vertexShader.replace('#include <worldpos_vertex>',`#include <worldpos_vertex>\nvec4 l0p=vec4(transformed,1.);vec3 l0n=normal;\n#ifdef USE_INSTANCING\nl0p=instanceMatrix*l0p;l0n=mat3(instanceMatrix)*l0n;\n#endif\nl0World=(modelMatrix*l0p).xyz;l0Normal=normalize(mat3(modelMatrix)*l0n);`);s.fragmentShader=s.fragmentShader.replace('#include <common>','#include <common>\nvarying vec3 l0World;varying vec3 l0Normal;\n'+cutGLSL);
  if(scale){const uv=`(abs(l0Normal.y)>.5?l0World.xz:(abs(l0Normal.x)>.5?l0World.zy:l0World.xy))/${Number(scale).toFixed(4)}`;s.fragmentShader=s.fragmentShader.replace('#include <map_fragment>',`#ifdef USE_MAP\nvec4 sampledDiffuseColor=texture2D(map,${uv});${grade}diffuseColor*=sampledDiffuseColor;\n#endif`);s.fragmentShader=s.fragmentShader.replace('#include <normal_fragment_maps>',`#ifdef USE_NORMALMAP_TANGENTSPACE\nvec3 mapN=texture2D(normalMap,${uv}).xyz*2.-1.;mapN.xy*=normalScale;normal=normalize(tbn*mapN);\n#endif`);}
  s.fragmentShader=s.fragmentShader.replace('#include <opaque_fragment>','outgoingLight*=circuitAt(l0World);\n#include <opaque_fragment>');};m.customProgramCacheKey=()=>`l0-v2-circuit-${scale||'uv'}-${remap||'raw'}`;}
 for(const m of Object.values(mats).flat())decorate(m);
 mats.outlets.forEach((m,i)=>mats["outlet"+i]=m);
 mats.ao=new T.ShaderMaterial({transparent:true,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-1,vertexShader:'varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*instanceMatrix*vec4(position,1.);}',fragmentShader:'varying vec2 vUv;void main(){float d=1.-max(abs(vUv.x-.5),abs(vUv.y-.5))*2.;gl_FragColor=vec4(.11,.095,.065,smoothstep(0.,.65,d)*.25);\n#include <colorspace_fragment>\n}',side:T.DoubleSide});
 uniforms.puddle={value:tex('carpet-puddle-albedo.jpg',true,true)};
 mats.water=new T.ShaderMaterial({transparent:true,depthWrite:false,side:T.DoubleSide,uniforms,vertexShader:'varying vec2 vUv;varying vec3 vWorld;void main(){vUv=uv;vec4 wp=modelMatrix*instanceMatrix*vec4(position,1.);vWorld=wp.xyz;gl_Position=projectionMatrix*viewMatrix*wp;}',fragmentShader:`uniform float time;uniform float brightness;uniform sampler2D puddle;varying vec2 vUv;varying vec3 vWorld;${cutGLSL}
 float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.54);}float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1)),f.x),f.y);}
 void main(){vec2 p=(vUv-.5)*2.;float edge=1.-smoothstep(.66,.96,length(p)+(noise(p*3.+vWorld.xz*.07)-.5)*.27);if(edge<.015)discard;vec3 eye=normalize(cameraPosition-vWorld);float f=pow(1.-max(eye.y,0.),4.);vec2 rp=vWorld.xz+(eye.xz/max(eye.y,.1))*2.72+sin(length(p)*82.-time*2.)*.002;vec2 grid=abs(mod(rp+1.8,3.6)-1.8);float reflection=(1.-smoothstep(.43,.56,grid.x))*(1.-smoothstep(.12,.23,grid.y));vec3 c=mix(vec3(.13,.11,.075),vec3(.40,.39,.31),f);c+=vec3(.78,.77,.66)*reflection*(.14+.5*f);c=mix(texture2D(puddle,vUv).rgb*.44,c,.75)*brightness*circuitAt(vWorld);gl_FragColor=vec4(c,edge*(.48+.27*f));\n#include <colorspace_fragment>\n}`});
 mats.pitWall=new T.ShaderMaterial({vertexShader:'varying float y;void main(){vec4 p=modelMatrix*instanceMatrix*vec4(position,1.);y=p.y;gl_Position=projectionMatrix*viewMatrix*p;}',fragmentShader:'varying float y;void main(){float a=exp(min(0.,y)*1.7);gl_FragColor=vec4(vec3(.29,.255,.16)*a,1.);\n#include <colorspace_fragment>\n}'});
 return{mats,uniforms,ready:Promise.all(pending)};
}
